<script setup lang="ts">import { onLoad } from '@dcloudio/uni-app'; import { ref } from 'vue'; import { manageApi } from '../../../api/manage'; import AdminGuard from '../../../components/admin/AdminGuard.vue'; import { authStore } from '../../../stores/auth'; const session=ref<any>({}); const id=ref(''); const open=(exchangeId:string|number)=>(globalThis as any).uni?.navigateTo?.({url:`/pages/admin/observability/exchange?conversationId=${id.value}&exchangeId=${exchangeId}`}); onLoad(async(q)=>{id.value=String(q?.conversationId||''); if(id.value && (await authStore.guard('/pages/admin/observability/session')) && authStore.isAdmin) session.value=await manageApi.getSession(id.value)})</script>
<template><AdminGuard route="/pages/admin/observability/session"><view class="page"><text class="title">会话链路</text><text class="id">{{ id }}</text><view v-for="item in (session.exchanges || session.messages || [])" :key="item.exchangeId || item.id" class="row" @click="open(item.exchangeId || item.id)">{{ item.question || item.content || JSON.stringify(item) }}</view></view></AdminGuard></template><style scoped>.page{padding:32rpx}.title{display:block;font-size:38rpx;font-weight:600}.id{display:block;color:var(--color-text-muted);margin:12rpx 0}.row{padding:20rpx 0;border-bottom:1rpx solid var(--color-border)}</style>
